rainbow_wave.glsl:
shader_type canvas_item;

uniform float speed : hint_range(0.0, 5.0) = 1.5;
uniform float frequency : hint_range(1.0, 20.0) = 6.0;
uniform float saturation : hint_range(0.0, 1.0) = 0.85;
uniform float brightness : hint_range(0.0, 1.0) = 0.95;

vec3 hsv2rgb(vec3 c) {
	vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
	vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
	return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void fragment() {
	vec4 tex = texture(TEXTURE, UV);
	float wave = sin(UV.x * frequency + UV.y * frequency * 0.7 + TIME * speed) * 0.5 + 0.5;
	float hue = fract(wave + TIME * 0.1);
	vec3 rainbow = hsv2rgb(vec3(hue, saturation, brightness));
	COLOR = vec4(rainbow * tex.rgb, tex.a);
}

